#include "bits/stdc++.h"
using namespace std;

int main() {
    int n, q;
    cin >> n >> q;
    vector<vector<int>> events;
    long long ans = 0;

    for (int i = 0;i < q;i++) {
        int l, r, c;
        cin >> l >> r >> c;
        l--, r--;
        events.push_back({ l, c, 1 });
        events.push_back({ r, c, 2 });
        ans += c;
    }
    sort(events.begin(), events.end());

    int idx = 0;
    multiset<int> st;
    for (int i = 0;i < n - 1;i++) {
        while (idx < events.size() && events[idx][0] == i) {
            if (events[idx][2] == 1) st.insert(events[idx][1]);
            else st.erase(st.find(events[idx][1]));
            idx++;
        }
        if (st.empty()) {
            cout << -1 << endl;
            return 0;
        }
        ans += *st.begin();
    }
    cout << ans << endl;
}
